function unauthorizedChallenge(reason) {
  const challenge =
    `Bearer realm="mcp", resource_metadata="${MCP_BASE}/.well-known/oauth-protected-resource"` +
    (reason ? `, error="${reason}"` : "");
  return {
    status: 401,
    headers: { "WWW-Authenticate": challenge },
    body: { error: { code: -2000, message: "authorization token is required" } },
  };
}

/**
 * Handle a compliant MCP request (full authenticated lifecycle).
 * Validates the Bearer token, checks the grant, and dispatches to the tool.
 * Uses per-request identity (no global CURRENT_CLAIMS slot) so concurrent
 * clients cannot observe each other's identity.
 */
function handleCompliantMcp(req, res, message) {
  const method = message && message.method;
  const id = message ? message.id : null;

  // Extract the Bearer token.
  const authHeader = req.headers["authorization"];
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    const c = unauthorizedChallenge("missing_token");
    sendJson(res, c.status, c.body, c.headers);
    return;
  }
  const token = authHeader.slice(7);

  // Validate the token (signature, iss, aud, exp, sub, client_id).
  const validation = provider.validateAccessToken(token);
  if (!validation.ok) {
    const c = unauthorizedChallenge(validation.error);
    sendJson(res, c.status, c.body, c.headers);
    return;
  }
  const claims = validation.claims;
  const sub = claims.sub;
  const client_id = claims.client_id;

  // Dispatch by method.
  if (method === "initialize") {
    sendJson(res, 200, {
      jsonrpc: "2.0",
      id,
      result: {
        protocolVersion: "2025-03-26",
        capabilities: { tools: {} },
        serverInfo: { name: "mock-standards-compliant", version: "1.0.0" },
      },
    });
    return;
  }

  if (method === "notifications/initialized") {
    // This is a notification (no id expected). Return 202 Accepted.
    res.writeHead(202, { "Content-Length": 0 });
    res.end();
    return;
  }

  if (method === "tools/list") {
    const tools = NINE_TOOLS.map((name) => ({
      name,
      ...TOOL_SCHEMAS[name],
    }));
    sendJson(res, 200, {
      jsonrpc: "2.0",
      id,
      result: { tools },
    });
    return;
  }

  if (method === "tools/call") {
    const toolName = message.params && message.params.name;
    if (toolName !== "calendar_list") {
      sendJson(res, 200, {
        jsonrpc: "2.0",
        id,
        error: { code: -32601, message: `Method not found: ${toolName}` },
      });
      return;
    }

    // Check the active grant for (sub, client_id).
    const grant = provider.getActiveGrant(sub, client_id);
    if (!grant) {
      sendJson(res, 200, {
        jsonrpc: "2.0",
        id,
        error: { code: -2003, message: "no MCP grant found" },
      });
      return;
    }

    // Filter calendars by the grant's allowed calendar IDs.
    const allCalendars = SUBJECT_CALENDARS[sub] || [];
    const filtered = allCalendars.filter((c) =>
      grant.allowed_calendar_ids.includes(c.id)
    );

    const output = { calendars: filtered };
    sendJson(res, 200, {
      jsonrpc: "2.0",
      id,
      result: {
        content: [
          {
            type: "text",
            text: JSON.stringify(output),
          },
        ],
      },
    });
    return;
  }

  // Unknown method.
  sendJson(res, 200, {
    jsonrpc: "2.0",
    id,
    error: { code: -32601, message: `Method not found: ${method}` },
  });
}

/**
 * Handle a current-production MCP request (mirrors mcp-server/src/gateway.rs).
 * Only tools/list and tools/call are recognized; everything else (including
 * initialize) is HTTP 400 with JSON-RPC -32601 and no WWW-Authenticate header.
 */
function handleCurrentMcp(req, res, message) {
  const method = message && message.method;
  const id = message ? message.id : null;

  if (method === "tools/list" || method === "tools/call") {
    // Current production: tools/list returns only {name} for each tool,
    // no description or inputSchema (mcp-server/src/gateway.rs:187-212).
    if (method === "tools/list") {
      const tools = NINE_TOOLS.map((name) => ({ name }));
      sendJson(res, 200, {
        jsonrpc: "2.0",
        id,
        result: { tools },
      });
    } else {
      // tools/call requires auth; the current production 401 builder
      // hard-codes the lab loopback URL (mcp-server/src/gateway.rs:456-541).
      const authHeader = req.headers["authorization"];
      if (!authHeader || !authHeader.startsWith("Bearer ")) {
        sendJson(
          res,
          401,
          { error: { code: -2000, message: "authorization token is required" } },
          {
            "WWW-Authenticate":
              'Bearer realm="mcp", resource_metadata="http://127.0.0.1:3001/.well-known/oauth-protected-resource", error="missing_token"',
          }
        );
      } else {
        // With a token, the current production would validate it and dispatch.
        // For the mock, we return a generic success.
        sendJson(res, 200, {
          jsonrpc: "2.0",
          id,
          result: { content: [{ type: "text", text: '{"calendars":[]}' }] },
        });
      }
    }
    return;
  }

  // Everything else (including initialize) is HTTP 400 with -32601.
  sendJson(res, 400, {
    jsonrpc: "2.0",
    id,
    error: { code: -32601, message: `Method not found: ${method}` },
  });
}

const mcpServer = http.createServer((req, res) => {
  if (req.method === "GET") {
    if (req.url === "/.well-known/oauth-protected-resource") {
      sendJson(res, 200, protectedResourceMetadata());
      return;
    }
    sendJson(res, 404, { error: "not found" });
    return;
  }

  if (req.method !== "POST") {
    sendJson(res, 405, { error: "method not allowed" });
    return;
  }

  let raw = "";
  req.on("data", (chunk) => {
    raw += chunk;
  });
  req.on("end", () => {
    let message = null;
    try {
      message = JSON.parse(raw);
    } catch {
      message = null;
    }

    if (COMPLIANT) {
      handleCompliantMcp(req, res, message);
      return;
    }
    handleCurrentMcp(req, res, message);
  });
});

const issuerServer = http.createServer((req, res) => {
  // In the current world the authorization service is not deployed; the
  // advertised issuer host is handled by core's "/" ingress and falls through
  // to the SPA (docs/MCP-PRODUCTION-FIX-PLAN.md). Every issuer route returns
  // the SPA HTML.
  if (!COMPLIANT) {
    sendHtml(res, 200, SPA_HTML);
    return;
  }

  if (req.method === "GET") {
    const parsedUrl = new URL(req.url, ISSUER_BASE);
    const pathname = parsedUrl.pathname;
    if (pathname === "/.well-known/oauth-authorization-server") {
      sendJson(res, 200, authorizationServerMetadata());
      return;
    }
    if (pathname === "/.well-known/openid-configuration") {
      // Verified current state: cal.hajnal.space returns the CommonCal SPA
      // HTML, not authorization-server metadata.
      sendHtml(res, 200, SPA_HTML);
      return;
    }
    if (pathname === "/jwks") {
      sendJson(res, 200, provider.jwks());
      return;
    }
    if (pathname === "/authorize") {
      // Authorization Code flow with S256 PKCE. Parse the query params.
      const params = parsedUrl.searchParams;
      const result = provider.handleAuthorize(params);
      if (result.status === 302 && result.location) {
        res.writeHead(302, { Location: result.location, "Content-Length": 0 });
        res.end();
      } else {
        sendJson(res, result.status, result.body);
      }
      return;
    }
    sendHtml(res, 200, SPA_HTML);
    return;
  }

  if (req.method === "POST") {
    let raw = "";
    req.on("data", (chunk) => {
      raw += chunk;
    });
    req.on("end", () => {
      if (req.url === "/register") {
        let body;
        try {
          body = JSON.parse(raw);
        } catch {
          body = {};
        }
        const result = provider.handleRegister(body);
        sendJson(res, result.status, result.body);
        return;
      }
      if (req.url === "/token") {
        // Token exchange: form-encoded body.
        const params = new URLSearchParams(raw);
        const result = provider.handleToken(params);
        if (result.status === 200 && result.body.access_token) {
          // Simulate CommonCal consent having approved a grant for the
          // authenticated subject (Phase 4 in production). The fixed lab
          // subject "1" is granted both of its calendars.
          const claims = decodeJwtPayload(result.body.access_token);
          if (claims && claims.sub && claims.client_id) {
            provider.upsertGrant(
              claims.sub,
              claims.client_id,
              [101, 102],
              SCOPE_CATALOG
            );
          }
        }
        sendJson(res, result.status, result.body);
        return;
      }
      // Verification-only test hooks (not part of the production contract).
      // The Phase 0.4 security harness uses these to drive grant-state cases
      // (missing / revoked / broadened) without depending on the lab binary.
      if (req.url === "/_test/grant/revoke") {
        let body;
        try {
          body = JSON.parse(raw);
        } catch {
          body = {};
        }
        provider.revokeGrant(body.sub, body.client_id);
        sendJson(res, 200, { revoked: true });
        return;
      }
      if (req.url === "/_test/grant/broaden") {
        let body;
        try {
          body = JSON.parse(raw);
        } catch {
          body = {};
        }
        // Broaden the grant to include calendars the subject does not own
        // (ids 999/998 do not exist in SUBJECT_CALENDARS), simulating an
        // attempted grant broadening that must be denied by the resource
        // server's live-membership check.
        provider.upsertGrant(
          body.sub,
          body.client_id,
          [101, 102, 999, 998],
          SCOPE_CATALOG
        );
        sendJson(res, 200, { broadened: true });
        return;
      }
      if (req.url === "/_test/grant/reset") {
        let body;
        try {
          body = JSON.parse(raw);
        } catch {
          body = {};
        }
        provider.upsertGrant(
          body.sub,
          body.client_id,
          [101, 102],
          SCOPE_CATALOG
        );
        sendJson(res, 200, { reset: true });
        return;
      }
      if (req.url === "/_test/grant/delete") {
        let body;
        try {
          body = JSON.parse(raw);
        } catch {
          body = {};
        }
        provider.deleteGrant(body.sub, body.client_id);
        sendJson(res, 200, { deleted: true });
        return;
      }
      // Verification-only test hook: set a grant with explicit allowed
      // calendar IDs. The Phase 0.4 security harness uses this to drive the
      // concurrency-isolation case (S9) with two different subjects, each
      // granted their own calendars.
      if (req.url === "/_test/grant/set") {
        let body;
        try {
          body = JSON.parse(raw);
        } catch {
          body = {};
        }
        const allowed = Array.isArray(body.allowed_calendar_ids)
          ? body.allowed_calendar_ids
          : [101, 102];
        provider.upsertGrant(body.sub, body.client_id, allowed, SCOPE_CATALOG);
        sendJson(res, 200, { set: true });
        return;
      }
      // Verification-only test hook: mint a token with specific claims, signed
      // with the provider's key. The Phase 0.4 security harness uses this to
      // drive the negative token cases (wrong issuer / audience / expiry /
      // client) with a VALID signature, so each claim check is exercised in
      // isolation (not masked by a signature failure). The "wrong signature"
      // case is driven by tampering a valid token's signature instead.
      if (req.url === "/_test/token/mint") {
        let body;
        try {
          body = JSON.parse(raw);
        } catch {
          body = {};
        }
        const claims = body.claims || {};
        const token = provider.mintToken(claims);
        sendJson(res, 200, { access_token: token });
        return;
      }
      sendJson(res, 404, { error: "not found" });
    });
    return;
  }

  sendJson(res, 405, { error: "method not allowed" });
});

mcpServer.listen(PORT, "127.0.0.1", () => {
  console.log(`[mock-lifecycle] world: ${WORLD}`);
  console.log(`[mock-lifecycle] MCP host on http://127.0.0.1:${PORT}`);
  console.log(`[mock-lifecycle] MCP endpoint: http://127.0.0.1:${PORT}/mcp`);
});

issuerServer.listen(ISSUER_PORT, "127.0.0.1", () => {
  console.log(`[mock-lifecycle] issuer host on http://127.0.0.1:${ISSUER_PORT}`);
});

"use strict";

/**
 * Verification-only mock OAuth authorization server for the Phase 0.3
 * (oauth-lifecycle) and Phase 0.4 (security-isolation) acceptance harnesses.
 *
 * This is NOT a release artifact and NOT the production authorization server.
 * It exists solely to exercise the harnesses' PASS and FAIL paths
 * deterministically. It is a self-contained, dependency-free OAuth provider
 * (DCR + Authorization Code + S256 PKCE + token exchange + JWKS) built on
 * Node built-ins only.
 *
 * It reuses the slice1-lab fixture shapes:
 *   - the DCR request shape (slice1-lab/negative_tests.py fresh_dcr,
 *     slice1-lab/auth-server/src/server.mjs validateRegisteredMetadata);
 *   - the standard access-token claim contract (slice1-lab/src/jwt.rs
 *     AccessClaims: iss, numeric sub, aud, exp, iat, client_id, scope, jti,
 *     amr);
 *   - the scope catalog (slice1-lab/src/common.rs SCOPE_CATALOG);
 *   - the negative-token / fail-closed cases (slice1-lab/negative_tests.py
 *     cases 3-9, slice1-lab/PROOF.md P7).
 *
 * It does NOT import lab code and does NOT launch the lab binaries. It owns
 * its own signing key (generated at startup), its own client/code/token
 * stores, and its own grant store.
 */

const crypto = require("node:crypto");

// ---------------------------------------------------------------------------
// Scope catalog (reused from slice1-lab/src/common.rs SCOPE_CATALOG)
// ---------------------------------------------------------------------------

const SCOPE_CATALOG = [
  "commoncal.calendar.metadata.read",
  "commoncal.availability.read",
  "commoncal.event.read.basic",
  "commoncal.event.read.details",
  "commoncal.event.create",
  "commoncal.event.update",
  "commoncal.event.delete",
  "commoncal.reminder.read",
  "commoncal.reminder.write",
];

// A scope deliberately outside the catalog (slice1-lab/src/common.rs EVIL_SCOPE).
const EVIL_SCOPE = "evil.unknown.scope";

// ---------------------------------------------------------------------------
// base64url helpers
// ---------------------------------------------------------------------------

function b64urlEncode(buf) {
  return Buffer.from(buf).toString("base64url");
}

function b64urlDecode(str) {
  return Buffer.from(str, "base64url");
}

function b64urlJson(obj) {
  return b64urlEncode(JSON.stringify(obj));
}

// ---------------------------------------------------------------------------
// RSA key + JWK + RS256 JWT
// ---------------------------------------------------------------------------

/**
 * Generate an RSA key pair and expose the public key as a JWK (n, e) plus a
 * signing function. The private key never leaves this module.
 */
function createSigningKey(kid) {
  const { publicKey, privateKey } = crypto.generateKeyPairSync("rsa", {
    modulusLength: 2048,
    publicKeyEncoding: { type: "spki", format: "pem" },
    privateKeyEncoding: { type: "pkcs8", format: "pem" },
  });

  // Extract n and e from the SPKI public key.
  const keyObj = crypto.createPublicKey(publicKey);
  const jwk = keyObj.export({ format: "jwk" });

  return {
    kid,
    jwk: {
      kty: "RSA",
      n: jwk.n,
      e: jwk.e,
      use: "sig",
      alg: "RS256",
      kid,
    },
    sign(payload) {
      const signer = crypto.createSign("RSA-SHA256");
      signer.update(payload);
      signer.end();
      // Output encoding is base64url; the signature format is DER (PKCS#1 v1.5),
      // which is what RSA-SHA256 produces by default.
      return signer.sign(privateKey, "base64url");
    },
  };
}

/**
 * Sign a JWT (RS256) with the given claims and signing key.
 */
function signJwt(claims, signingKey) {
  const header = { alg: "RS256", typ: "JWT", kid: signingKey.kid };
  const signingInput = `${b64urlJson(header)}.${b64urlJson(claims)}`;
  const signature = signingKey.sign(signingInput);
  return `${signingInput}.${signature}`;
}

/**
 * Verify an RS256 JWT signature against a JWK. Returns true if valid.
 */
function verifyJwtSignature(jwt, jwk) {
  const parts = jwt.split(".");
  if (parts.length !== 3) return false;
  const [headerB64, payloadB64, signatureB64] = parts;
  let header;
  try {
    header = JSON.parse(b64urlDecode(headerB64).toString("utf8"));
  } catch {
    return false;
  }
  if (header.alg !== "RS256") return false;
  if (jwk.kty !== "RSA" || !jwk.n || !jwk.e) return false;

  // Reconstruct the RSA public key from the JWK (n, e). Node handles the
  // modulus padding internally for the JWK->key conversion.
  let publicKey;
  try {
    publicKey = crypto.createPublicKey({
      key: { kty: "RSA", n: jwk.n, e: jwk.e },
      format: "jwk",
    });
  } catch {
    return false;
  }

  const verifier = crypto.createVerify("RSA-SHA256");
  verifier.update(`${headerB64}.${payloadB64}`);
  verifier.end();
  try {
    // Pass the signature as a Buffer (default 'buffer' format).
    return verifier.verify(publicKey, b64urlDecode(signatureB64));
  } catch {
    return false;
  }
}

/**
 * Decode a JWT payload (no signature verification). Returns the claims object
 * or null.
 */
function decodeJwtPayload(jwt) {
  const parts = jwt.split(".");
  if (parts.length !== 3) return null;
  try {
    return JSON.parse(b64urlDecode(parts[1]).toString("utf8"));
  } catch {
    return null;
  }
}

/**
 * Decode a JWT header (no signature verification). Returns the header object
 * or null.
 */
function decodeJwtHeader(jwt) {
  const parts = jwt.split(".");
  if (parts.length !== 3) return null;
  try {
    return JSON.parse(b64urlDecode(parts[0]).toString("utf8"));
  } catch {
    return null;
  }
}

// ---------------------------------------------------------------------------
// PKCE S256
// ---------------------------------------------------------------------------

/**
 * Compute the S256 code challenge for a verifier (RFC 7636).
 */
function s256Challenge(verifier) {
  return b64urlEncode(crypto.createHash("sha256").update(verifier).digest());
}

// ---------------------------------------------------------------------------
// The mock OAuth provider
// ---------------------------------------------------------------------------

/**
 * A self-contained mock OAuth authorization server.
 *
 * @param {object} opts
 * @param {string} opts.issuer      The issuer base URL (e.g. http://127.0.0.1:PORT).
 * @param {string} opts.resource    The exact MCP resource / audience.
 * @param {string} opts.redirect    The admitted loopback redirect URI.
 * @param {string} [opts.kid]       The signing key id.
 */
class MockOAuthProvider {
  constructor({ issuer, resource, redirect, kid = "mcp-acceptance-rs256" }) {
    this.issuer = issuer.replace(/\/$/, "");
    this.resource = resource;
    this.redirect = redirect;
    this.signingKey = createSigningKey(kid);

    // Stores.
    this.clients = new Map(); // client_id -> client metadata
    this.codes = new Map(); // code -> { client_id, redirect_uri, challenge, scope, sub, used }
    this.tokens = new Map(); // jti -> { client_id, sub, scope, aud, exp, iat }
    this.grants = new Map(); // `${sub}:${client_id}` -> grant

    this.clientSeq = 0;
  }

  // -- DCR ------------------------------------------------------------------

  /**
   * Handle a DCR (RFC 7591) registration request. Mirrors the lab's DCR
   * policy (slice1-lab/auth-server/src/server.mjs validateRegisteredMetadata):
   * exactly one loopback redirect, grant_types [authorization_code,
   * refresh_token], response_types [code], token_endpoint_auth_method none.
   *
   * @returns {{status: number, body: object}}
   */
  handleRegister(body) {
    const redirectUris = body.redirect_uris;
    if (!Array.isArray(redirectUris) || redirectUris.length !== 1) {
      return { status: 400, body: { error: "invalid_redirect_uris" } };
    }
    if (redirectUris[0] !== this.redirect) {
      return {
        status: 400,
        body: {
          error: "invalid_redirect_uri",
          error_description: `only the admitted loopback ${this.redirect} is allowed`,
        },
      };
    }
    const grantTypes = Array.isArray(body.grant_types) ? [...body.grant_types].sort() : [];
    if (
      JSON.stringify(grantTypes) !==
      JSON.stringify(["authorization_code", "refresh_token"])
    ) {
      return { status: 400, body: { error: "invalid_grant_types" } };
    }
    const responseTypes = Array.isArray(body.response_types) ? body.response_types : [];
    if (responseTypes.length !== 1 || responseTypes[0] !== "code") {
      return { status: 400, body: { error: "invalid_response_types" } };
    }
    if (body.token_endpoint_auth_method !== "none") {
      return { status: 400, body: { error: "invalid_token_endpoint_auth_method" } };
    }

    this.clientSeq += 1;
    const client_id = `mcp-acceptance-client-${this.clientSeq}`;
    const client = {
      client_id,
      client_name: body.client_name ?? "mcp-acceptance",
      redirect_uris: [this.redirect],
      grant_types: ["authorization_code", "refresh_token"],
      response_types: ["code"],
      token_endpoint_auth_method: "none",
      scope: body.scope ?? SCOPE_CATALOG.join(" "),
    };
    this.clients.set(client_id, client);
    return { status: 201, body: client };
  }

  // -- Authorization --------------------------------------------------------

  /**
   * Handle an authorization request. In the mock, login + consent are
   * auto-approved (the lab's stub adapter / CommonCal consent is the identity
   * authority; the mock stands in for it). It issues an authorization code
   * bound to the client, redirect URI, PKCE challenge, scope, and subject.
   *
   * @param {object} params  URLSearchParams of the authorization request.
   * @returns {{status: number, body: object, location?: string}}
   */
  handleAuthorize(params) {
    const client_id = params.get("client_id");
    const client = this.clients.get(client_id);
    if (!client) {
      return { status: 400, body: { error: "unknown_client" } };
    }
    const redirect_uri = params.get("redirect_uri");
    if (redirect_uri !== this.redirect) {
      return { status: 400, body: { error: "invalid_redirect_uri" } };
    }
    const response_type = params.get("response_type");
    if (response_type !== "code") {
      return { status: 400, body: { error: "unsupported_response_type" } };
    }
    const code_challenge = params.get("code_challenge");
    const code_challenge_method = params.get("code_challenge_method");
    if (!code_challenge || code_challenge_method !== "S256") {
      return { status: 400, body: { error: "invalid_request", error_description: "S256 PKCE required" } };
    }
    const scope = params.get("scope") ?? "";
    const state = params.get("state") ?? "";

    // The subject is a CommonCal user id (numeric). The mock stands in for
    // CommonCal's identity authority and binds the fixed lab subject "1".
    const sub = "1";

    const code = `mcp-acceptance-code-${crypto.randomBytes(12).toString("hex")}`;
    this.codes.set(code, {
      client_id,
      redirect_uri,
      challenge: code_challenge,
      scope,
      sub,
      used: false,
    });

    const location = `${this.redirect}?code=${encodeURIComponent(code)}&state=${encodeURIComponent(state)}`;
    return { status: 302, body: {}, location };
  }

  // -- Token ----------------------------------------------------------------

  /**
   * Handle a token exchange (Authorization Code + S256 PKCE). Verifies the
   * code, the PKCE verifier, and the redirect URI, then issues a JWT access
   * token with the standard claim contract.
   *
   * @param {object} params  URLSearchParams of the token request.
   * @returns {{status: number, body: object}}
   */
  handleToken(params) {
    const grant_type = params.get("grant_type");
    if (grant_type !== "authorization_code") {
      return { status: 400, body: { error: "unsupported_grant_type" } };
    }
    const code = params.get("code");
    const entry = this.codes.get(code);
    if (!entry) {
      return { status: 400, body: { error: "invalid_grant", error_description: "unknown or expired code" } };
    }
    if (entry.used) {
      return { status: 400, body: { error: "invalid_grant", error_description: "code already redeemed" } };
    }
    const client_id = params.get("client_id");
    if (client_id !== entry.client_id) {
      return { status: 400, body: { error: "invalid_grant", error_description: "client_id mismatch" } };
    }
    const redirect_uri = params.get("redirect_uri");
    if (redirect_uri !== entry.redirect_uri) {
      return { status: 400, body: { error: "invalid_grant", error_description: "redirect_uri mismatch" } };
    }
    const code_verifier = params.get("code_verifier");
    if (!code_verifier) {
      return { status: 400, body: { error: "invalid_request", error_description: "code_verifier required" } };
    }
    if (s256Challenge(code_verifier) !== entry.challenge) {
      return { status: 400, body: { error: "invalid_grant", error_description: "PKCE verifier mismatch" } };
    }

    entry.used = true;

    // The granted scopes are the intersection of requested and catalog
    // (slice1-lab/auth-server/src/server.mjs approvedResourceScopes).
    const requested = new Set(String(entry.scope).split(" ").filter(Boolean));
    const granted = SCOPE_CATALOG.filter((s) => requested.has(s));

    const now = Math.floor(Date.now() / 1000);
    const jti = `mcp-acceptance-jti-${crypto.randomBytes(12).toString("hex")}`;
    const claims = {
      iss: this.issuer,
      sub: entry.sub,
      aud: this.resource,
      exp: now + 300,
      iat: now,
      jti,
      client_id: entry.client_id,
      scope: granted.join(" "),
      amr: ["pwd"],
    };
    const access_token = signJwt(claims, this.signingKey);
    this.tokens.set(jti, {
      client_id: entry.client_id,
      sub: entry.sub,
      scope: granted.join(" "),
      aud: this.resource,
      exp: claims.exp,
      iat: now,
    });

    return {
      status: 200,
      body: {
        access_token,
        token_type: "Bearer",
        expires_in: 300,
        refresh_token: `mcp-acceptance-refresh-${crypto.randomBytes(12).toString("hex")}`,
        scope: granted.join(" "),
      },
    };
  }

  // -- JWKS -----------------------------------------------------------------

  /**
   * The JWKS document (public key only).
   */
  jwks() {
    return { keys: [this.signingKey.jwk] };
  }

  // -- Token validation (resource-server side) ------------------------------

  /**
   * Validate an access token the way the production MCP server must:
   * signature (via JWKS), exact iss, exact aud, exp, and the standard claims.
   * Returns { ok, claims?, error? }.
   */
  validateAccessToken(token) {
    if (typeof token !== "string" || token.split(".").length !== 3) {
      return { ok: false, error: "malformed_token" };
    }
    const header = decodeJwtHeader(token);
    if (!header || header.alg !== "RS256") {
      return { ok: false, error: "unsupported_alg" };
    }
    const kid = header.kid;
    if (kid !== this.signingKey.kid) {
      return { ok: false, error: "unknown_kid" };
    }
    if (!verifyJwtSignature(token, this.signingKey.jwk)) {
      return { ok: false, error: "invalid_signature" };
    }
    const claims = decodeJwtPayload(token);
    if (!claims) {
      return { ok: false, error: "malformed_payload" };
    }
    if (claims.iss !== this.issuer) {
      return { ok: false, error: "invalid_issuer" };
    }
    const aud = Array.isArray(claims.aud) ? claims.aud : [claims.aud];
    if (!aud.includes(this.resource)) {
      return { ok: false, error: "invalid_audience" };
    }
    const now = Math.floor(Date.now() / 1000);
    if (typeof claims.exp !== "number" || claims.exp <= now) {
      return { ok: false, error: "token_expired" };
    }
    if (typeof claims.sub !== "string" || !/^\d+$/.test(claims.sub)) {
      return { ok: false, error: "invalid_sub" };
    }
    if (typeof claims.client_id !== "string" || !this.clients.has(claims.client_id)) {
      return { ok: false, error: "unknown_client" };
    }
    return { ok: true, claims };
  }

  // -- Token minting (verification-only) ------------------------------------

  /**
   * Mint a token with the given claims, signed with the provider's key.
   *
   * This is a verification-only helper used by the Phase 0.4 security harness
   * to drive the negative token cases (wrong issuer / audience / expiry /
   * client) with a VALID signature, so each claim check is exercised in
   * isolation (not masked by a signature failure). It is NOT part of the
   * production contract and is only reachable through the mock's `/_test/*`
   * hooks.
   *
   * @param {object} claims  The claims to embed in the token.
   * @returns {string} A signed JWT.
   */
  mintToken(claims) {
    const now = Math.floor(Date.now() / 1000);
    const fullClaims = {
      iss: this.issuer,
      sub: "1",
      aud: this.resource,
      exp: now + 300,
      iat: now,
      jti: `mcp-acceptance-mint-${crypto.randomBytes(12).toString("hex")}`,
      client_id: "mcp-acceptance-client-1",
      scope: SCOPE_CATALOG.join(" "),
      amr: ["pwd"],
      ...claims,
    };
    return signJwt(fullClaims, this.signingKey);
  }

  // -- Grants ---------------------------------------------------------------

  /**
   * Create an active grant for (sub, client_id) with the given allowed
   * calendar ids and scopes. Mirrors slice1-lab/src/bin/commoncal.rs
   * upsert_grant (replace semantics).
   */
  upsertGrant(sub, client_id, allowedCalendarIds, scopes) {
    const key = `${sub}:${client_id}`;
    this.grants.set(key, {
      sub,
      client_id,
      allowed_calendar_ids: allowedCalendarIds,
      scopes,
      revoked: false,
    });
  }

  /**
   * Revoke the active grant for (sub, client_id).
   */
  revokeGrant(sub, client_id) {
    const key = `${sub}:${client_id}`;
    const grant = this.grants.get(key);
    if (grant) grant.revoked = true;
  }

  /**
   * Delete the grant for (sub, client_id) entirely (simulates a missing grant).
   */
  deleteGrant(sub, client_id) {
    this.grants.delete(`${sub}:${client_id}`);
  }

  /**
   * Get the active grant for (sub, client_id), or null.
   */
  getActiveGrant(sub, client_id) {
    const grant = this.grants.get(`${sub}:${client_id}`);
    if (!grant || grant.revoked) return null;
    return grant;
  }
}

module.exports = {
  MockOAuthProvider,
  SCOPE_CATALOG,
  EVIL_SCOPE,
  b64urlEncode,
  b64urlDecode,
  b64urlJson,
  createSigningKey,
  signJwt,
  verifyJwtSignature,
  decodeJwtPayload,
  decodeJwtHeader,
  s256Challenge,
};

#!/usr/bin/env node
"use strict";

/**
 * Self-contained verification for the Phase 0.3 MCP oauth-lifecycle harness.
 *
 * This script proves oauth-lifecycle.js behaves correctly on BOTH paths:
 *
 *   1. FAIL path — against a server that exhibits the CURRENT production
 *      behavior (DCR returns SPA HTML, no OAuth flow), the harness must exit 1
 *      with focused violations on L1 (DCR), L2 (authorization), and L3
 *      (token exchange).
 *   2. PASS path — against a server that implements the full OAuth + MCP
 *      lifecycle, the harness must exit 0.
 *
 * It starts the verification-only mock server (mock/lifecycle-server.js) as a
 * child process, runs the harness (oauth-lifecycle.js) as a child process
 * against each endpoint, asserts the expected exit codes, and cleans up the
 * mock server.
 *
 * This is a test harness for the harness; it is not a release artifact and
 * does not touch production.
 *
 * Run:  node mcp-acceptance/verify-oauth-lifecycle.js
 * Exit: 0 if both paths behave as expected, 1 otherwise.
 */

const { spawn, execFile } = require("node:child_process");
const path = require("node:path");

const HERE = __dirname;
const MOCK = path.join(HERE, "mock", "lifecycle-server.js");
const HARNESS = path.join(HERE, "oauth-lifecycle.js");

function flagValue(argv, name, fallback) {
  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];
    if (arg === `--${name}`) return argv[i + 1];
    if (arg.startsWith(`--${name}=`)) return arg.slice(name.length + 3);
  }
  const envVal = process.env[name.toUpperCase()];
  return envVal !== undefined && envVal !== "" ? envVal : fallback;
}

const PORT = Number(flagValue(process.argv.slice(2), "port", process.env.MOCK_PORT || 4001));
const MCP_BASE = `http://127.0.0.1:${PORT}`;
const ISSUER_BASE = `http://127.0.0.1:${PORT + 1}`;

function log(msg) {
  console.log(`[verify-oauth-lifecycle] ${msg}`);
}

function runHarness(url, issuer, world) {
  return new Promise((resolve) => {
    execFile(
      process.execPath,
      [HARNESS, "--url", url, "--issuer", issuer, "--timeout-ms", "5000"],
      { timeout: 20000 },
      (error, stdout, stderr) => {
        const exitCode =
          error === null ? 0 : typeof error.code === "number" ? error.code : -1;
        resolve({ exitCode, stdout, stderr });
      }
    );
  });
}

async function waitForServer(url, timeoutMs = 10000) {
  const start = Date.now();
  while (Date.now() - start < timeoutMs) {
    try {
      const res = await fetch(url);
      void res.status;
      await res.arrayBuffer();
      return true;
    } catch {
      await new Promise((r) => setTimeout(r, 100));
    }
  }
  return false;
}

function startMock(world) {
  return new Promise((resolve) => {
    const mock = spawn(process.execPath, [MOCK], {
      env: { ...process.env, MOCK_PORT: String(PORT), MOCK_WORLD: world },
      stdio: ["ignore", "pipe", "pipe"],
    });
    let mockOutput = "";
    mock.stdout.on("data", (d) => {
      mockOutput += d.toString();
    });
    mock.stderr.on("data", (d) => {
      mockOutput += d.toString();
    });
    resolve({ mock, getOutput: () => mockOutput });
  });
}

async function main() {
  let allPassed = true;
  const check = (label, ok) => {
    log(`  ${label} -> ${ok ? "OK" : "MISMATCH"}`);
    if (!ok) allPassed = false;
  };

  // 1. FAIL path: current-production behavior -> harness must exit 1.
  log("FAIL path: harness vs current-production behavior (expect exit 1)");
  const { mock: mockFail, getOutput: getFailOutput } = await startMock("current");
  const upFail = await waitForServer(`${MCP_BASE}/.well-known/oauth-protected-resource`);
  if (!upFail) {
    log("ERROR: mock server (current) did not become ready");
    log(getFailOutput());
    mockFail.kill("SIGTERM");
    return 1;
  }
  const fail = await runHarness(`${MCP_BASE}/mcp`, ISSUER_BASE, "current");
  check(`harness exit code: ${fail.exitCode} (expected 1)`, fail.exitCode === 1);
  check(
    "violation L1 (DCR) present",
    fail.stdout.includes("L1:")
  );
  mockFail.kill("SIGTERM");
  await new Promise((r) => setTimeout(r, 200));

  // 2. PASS path: compliant behavior -> harness must exit 0.
  log("PASS path: harness vs compliant lifecycle server (expect exit 0)");
  const { mock: mockPass, getOutput: getPassOutput } = await startMock("compliant");
  const upPass = await waitForServer(`${MCP_BASE}/.well-known/oauth-protected-resource`);
  if (!upPass) {
    log("ERROR: mock server (compliant) did not become ready");
    log(getPassOutput());
    mockPass.kill("SIGTERM");
    return 1;
  }
  const pass = await runHarness(`${MCP_BASE}/mcp`, ISSUER_BASE, "compliant");
  check(`harness exit code: ${pass.exitCode} (expected 0)`, pass.exitCode === 0);
  check("L1 passes", pass.stdout.includes("L1: PASS"));
  check("L2 passes", pass.stdout.includes("L2: PASS"));
  check("L3 passes", pass.stdout.includes("L3: PASS"));
  check("L4 passes", pass.stdout.includes("L4: PASS"));
  check("L5 passes", pass.stdout.includes("L5: PASS"));
  check("L6 passes", pass.stdout.includes("L6: PASS"));
  check("L7 passes", pass.stdout.includes("L7: PASS"));
  mockPass.kill("SIGTERM");
  await new Promise((r) => setTimeout(r, 200));

  log("");
  if (allPassed) {
    log("VERIFY PASS: oauth-lifecycle harness exits 1 on current-production behavior and 0 on compliant behavior.");
    return 0;
  }
  log("VERIFY FAIL: oauth-lifecycle harness behavior did not match expectations.");
  return 1;
}

main()
  .then((code) => {
    process.exitCode = code;
  })
  .catch((err) => {
    console.error(`[verify-oauth-lifecycle] UNEXPECTED ERROR: ${err && err.message ? err.message : String(err)}`);
    if (err && err.stack) console.error(err.stack);
    process.exitCode = 1;
  });

